# Let's try a different approach - use Z3 or encode as SAT
# First, let's think about what edges we need to add

# The current graph has a large independent set. To reduce it to <=5,
# we need to add edges that "break" all independent sets of size 6.

# Let's enumerate all independent sets of size 6 in the current graph
# (before adding any edges), since adding edges can only reduce independent sets.

import itertools

fixed_edges = [(6,14), (13,14), (0,12), (2,11), (2,10), (8,14), (7,14), (6,15), (5,13), (12,15), (2,14), (0,11), (0,8), (8,15), (14,15), (4,5), (5,7), (2,13), (0,2), (0,1), (0,10), (0,5), (10,11), (3,7)]

adj = {i: set() for i in range(16)}
for u,v in fixed_edges:
    adj[u].add(v)
    adj[v].add(u)

# All possible non-fixed edges
all_possible_edges = [(u,v) for u in range(16) for v in range(u+1, 16) if v not in adj[u]]
print(f"Number of possible edges to add: {len(all_possible_edges)}")

# Let's find all independent sets of size 6 in the current graph
# (these are the ones we need to "break" by adding at least one edge inside each)
ind_sets_size_6 = []
for combo in itertools.combinations(range(16), 6):
    ok = True
    for i in range(6):
        for j in range(i+1, 6):
            if combo[j] in adj[combo[i]]:
                ok = False
                break
        if not ok:
            break
    if ok:
        ind_sets_size_6.append(combo)

print(f"Number of independent sets of size 6: {len(ind_sets_size_6)}")

# For each such set, we need to add at least one edge between two vertices in the set
# This is a hitting set problem!

# Let's also check independent sets of size 7, 8, 9, etc.
for sz in range(6, 10):
    count = 0
    for combo in itertools.combinations(range(16), sz):
        ok = True
        for i in range(sz):
            for j in range(i+1, sz):
                if combo[j] in adj[combo[i]]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            count += 1
    print(f"Independent sets of size {sz}: {count}")

