from pysat.formula import CNF
from pysat.solvers import Glucose3

fixed_edges = [(6,14), (13,14), (0,12), (2,11), (2,10), (8,14), (7,14), (6,15), (5,13), (12,15), (2,14), (0,11), (0,8), (8,15), (14,15), (4,5), (5,7), (2,13), (0,2), (0,1), (0,10), (0,5), (10,11), (3,7)]

adj = {i: set() for i in range(16)}
for u,v in fixed_edges:
    adj[u].add(v)
    adj[v].add(u)

# All possible non-fixed edges
all_possible_edges = [(u,v) for u in range(16) for v in range(u+1, 16) if v not in adj[u]]
edge_to_var = {e: i+1 for i, e in enumerate(all_possible_edges)}
var_to_edge = {i+1: e for i, e in enumerate(all_possible_edges)}
n_vars = len(all_possible_edges)

print(f"Number of edge variables: {n_vars}")

# Find all independent sets of size 6
ind_sets_size_6 = []
for combo in itertools.combinations(range(16), 6):
    ok = True
    for i in range(6):
        for j in range(i+1, 6):
            if combo[j] in adj[combo[i]]:
                ok = False
                break
        if not ok:
            break
    if ok:
        ind_sets_size_6.append(combo)

print(f"Number of independent sets of size 6: {len(ind_sets_size_6)}")

# For each independent set of size 6, we need at least one edge inside it
# That means: for each such set S, at least one of the possible edges (u,v) with u,v in S must be added
# This is a hitting set / clause constraint

# Build CNF
cnf = CNF()

# For each independent set of size 6, add clause: at least one edge inside it
for iset in ind_sets_size_6:
    clause = []
    for i in range(6):
        for j in range(i+1, 6):
            u, v = iset[i], iset[j]
            if v not in adj[u]:  # edge not already present
                e = (min(u,v), max(u,v))
                clause.append(edge_to_var[e])
    if clause:
        cnf.append(clause)

print(f"Number of clauses: {len(cnf.clauses)}")

# Also need connectivity constraint - vertex 9 must connect to the rest
# This is harder to encode in SAT directly. Let me first try without connectivity
# and then check if the solution is connected.

solver = Glucose3(cnf)
if solver.solve():
    model = solver.get_model()
    added_edges = []
    for v in model:
        if v > 0:
            added_edges.append(var_to_edge[v])
    print(f"Found solution with {len(added_edges)} added edges")
    print(f"Added edges: {added_edges}")

    # Build the new graph
    new_adj = {i: set(adj[i]) for i in range(16)}
    for u,v in added_edges:
        new_adj[u].add(v)
        new_adj[v].add(u)

    # Check connectivity
    visited = set()
    stack = [0]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for nb in new_adj[v]:
            if nb not in visited:
                stack.append(nb)
    print(f"Connected: {len(visited) == 16}")
    print(f"Vertices reachable from 0: {sorted(visited)}")

    # Check max independent set
    # Find max independent set (this might be slow, let's just check size 6)
    has_size_6 = False
    for combo in itertools.combinations(range(16), 6):
        ok = True
        for i in range(6):
            for j in range(i+1, 6):
                if combo[j] in new_adj[combo[i]]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            has_size_6 = True
            print(f"Found independent set of size 6: {combo}")
            break
    print(f"Has independent set of size 6: {has_size_6}")
else:
    print("UNSATISFIABLE - no graph exists with these constraints")

